const r = await tools.exec_command({
  cmd: "nvidia-smi --id=1,7 --query-gpu=index,uuid,memory.used,utilization.gpu --format=csv,noheader,nounits; nvidia-smi --id=1,7 --query-compute-apps=gpu_uuid,pid,process_name,used_memory --format=csv,noheader,nounits; ps -eo pid,ppid,pgid,sid,args | rg '/data/di/worldarena2_track1_20260815/official_track1_eval' | rg -v 'rg '",
  workdir: "/data/fjy/worldarena",
  yield_time_ms: 10000,
  max_output_tokens: 12000,
  sandbox_permissions: "require_escalated",
  justification: "允许我核实 GPU7 当前 Track 1 的精确 PID/PGID，以便仅停止该组并并行运行 SSE12 hold truth 吗？"
});
text(r.output);

const r = await tools.exec_command({
  cmd: "kill -TERM -- -1293842; sleep 3; ps -eo pid,ppid,pgid,sid,args | awk '$3==1293842 {print}'; nvidia-smi --id=7 --query-gpu=memory.used,utilization.gpu --format=csv,noheader,nounits",
  workdir: "/data/fjy/worldarena",
  yield_time_ms: 10000,
  max_output_tokens: 5000,
  sandbox_permissions: "require_escalated",
  justification: "允许我终止已核实的 GPU7 Track 1 PGID 1293842 并验证显存释放吗？"
});
text(r.output);

const results = await Promise.all([0,1].map(shard => tools.exec_command({
  cmd: `bash scripts/run_track2_w0_sse12_hold_shard_v1.sh ${shard}`,
  workdir: "/data/fjy/worldarena",
  yield_time_ms: 1000,
  max_output_tokens: 3000,
  sandbox_permissions: "require_escalated",
  justification: `允许我在已释放的 GPU${shard === 0 ? 1 : 7} 上启动 SSE12 hold truth shard ${shard} 吗？`,
  prefix_rule: ["bash", "scripts/run_track2_w0_sse12_hold_shard_v1.sh"]
})));
results.forEach((r,i)=>text(JSON.stringify({shard:i,...r})));
